SELECT Имена_станций.NAME, St.NUMB1120, St.Year, St.NUST, St.B, St.GAZ, St.ISK_GAZ, St.MAZUT, St.TORF, St.SLAN, St.PROCH, Dop.domen_g, Dop.koks_g, Dop.prochgaz, Dop.tvproch, Dop.szh_gaz, Dop.inoe, St.UGOL, St.DON, St.PODM, St.PECH, St.ARKT, St.KUZN, St.URAL, St.BASHK, St.KAZAH, St.KAN, St.TUNG, St.IRKUT, St.HAK, St.TUV, St.BUR, St.CHIT, St.AMUR, St.PRIM, St.URG, St.USHUM, St.YAKUT, St.MAG, St.SAH, St.KAMCH, St.CHUKOT, Dop.gazpp, Dop.intin, Dop.vork, Dop.kuzngd, Dop.kuznt, Dop.kuznss, Dop.kuznun, Dop.sver, Dop.chel, Dop.kizel, Dop.ekib, Dop.maikub, Dop.nazar, Dop.ibor, Dop.berez, Dop.per, Dop.irbei, Dop.kansk, Dop.jer, Dop.karab, Dop.azey, Dop.mug, Dop.cher, Dop.gusin, Dop.tugn, Dop.okino, Dop.har, Dop.urt, Dop.tataur, Dop.tarbag, Dop.zab_kam, Dop.neru, Dop.zyryan, Dop.pyak, Dop.rai, Dop.erk, Dop.bikin, Dop.razdol, Dop.hankai, Dop.anad, Dop.bering, Dop.gaz_prir, Dop.disel, Dop.maztop, Dop.gtt, Dop.nft_proch, Dop.ogodj, Dop.svo, Dop.karag, Dop.karajyra, Dop.teniz
FROM Имена_станций INNER JOIN (Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN (Станции2024 AS St LEFT JOIN Доп_угли2024 AS Dop ON (St.YEAR = Dop.YEAR) AND (St.NUMB1120 = Dop.NUMB1120)) ON Имена_ОЭС.oes = St.OES) ON Имена_областей.OBL = St.OBL) ON Имена_станций.NUMB = St.NUMB1120
WHERE (((St.B)>0))
ORDER BY Имена_станций.ordnumb;
